def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    # Convert text-based booking_date values into proper DATE values.
    # Handles formats: YYYY-MM-DD, DD-MM-YYYY, DD/MM/YYYY, DD.MM.YYYY. Others become NULL.
    using_expr = (
        "CASE "
        "WHEN booking_date IS NULL OR trim(booking_date) = '' THEN NULL "
        "WHEN booking_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN booking_date::date "
        "WHEN booking_date ~ '^[0-9]{2}-[0-9]{2}-[0-9]{4}$' THEN to_date(booking_date,'DD-MM-YYYY') "
        "WHEN booking_date ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN to_date(booking_date,'DD/MM/YYYY') "
        "WHEN booking_date ~ '^[0-9]{2}\\.[0-9]{2}\\.[0-9]{4}$' THEN to_date(booking_date,'DD.MM.YYYY') "
        "ELSE NULL END"
    )
    op.alter_column(
        'transaction',
        'booking_date',
        existing_type=sa.VARCHAR(),
        type_=sa.Date(),
        existing_nullable=True,
        postgresql_using=using_expr,
    )
    # ### end Alembic commands ###


